CREATE DATABASE IF NOT EXISTS wudoaba_school CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE wudoaba_school;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','teacher','parent','pupil') NOT NULL,full_name VARCHAR(150) NOT NULL,active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE classes(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) UNIQUE NOT NULL);
CREATE TABLE pupils(id INT AUTO_INCREMENT PRIMARY KEY,admission_number VARCHAR(50) UNIQUE NOT NULL,first_name VARCHAR(80) NOT NULL,middle_name VARCHAR(80),last_name VARCHAR(80) NOT NULL,date_of_birth DATE,gender VARCHAR(20),class_id INT NOT NULL,parent_name VARCHAR(150),parent_phone VARCHAR(40),FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE admissions(id INT AUTO_INCREMENT PRIMARY KEY,parent_name VARCHAR(150) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(150),pupil_name VARCHAR(150) NOT NULL,class_applied VARCHAR(50) NOT NULL,message TEXT,status ENUM('new','reviewing','accepted','rejected') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE news(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,category VARCHAR(80),published TINYINT DEFAULT 1,author_id INT,published_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE results(id INT AUTO_INCREMENT PRIMARY KEY,pupil_id INT NOT NULL,subject VARCHAR(100) NOT NULL,term VARCHAR(30) NOT NULL,academic_year VARCHAR(20) NOT NULL,score DECIMAL(5,2) NOT NULL,grade VARCHAR(5),remark VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(pupil_id) REFERENCES pupils(id) ON DELETE CASCADE);
CREATE TABLE attendance(id INT AUTO_INCREMENT PRIMARY KEY,pupil_id INT NOT NULL,date DATE NOT NULL,status ENUM('Present','Absent','Late','Excused') NOT NULL,remarks VARCHAR(255),recorded_by INT,UNIQUE KEY pupil_date(pupil_id,date),FOREIGN KEY(pupil_id) REFERENCES pupils(id) ON DELETE CASCADE,FOREIGN KEY(recorded_by) REFERENCES users(id) ON DELETE SET NULL);
